module compressor4_2 (
    input  x1,
    input  x2,
    input  x3,
    input  x4,
    input  cin,
    output sum,
    output carry,
    output cout
);

    assign sum = (x1 ^ x2) ^ (x3 ^ cin) ^ x4;
    assign cout = ((x1 & x2) | (x1 & x3) | (x2 & x3));
    assign carry = ((x1 ^ x2) ^ (x3 ^ cin)) ? x4 : cin;

endmodule

module compressor3_2 (
    input  x1,
    input  x2,
    input  x3,
    output sum,
    output cout
);

    assign sum = x1 ^ x2 ^ x3;
    assign cout = (x1 & x2) | (x2 & x3) | (x3 & x1);

endmodule

module csa #(
    parameter n = 5
)(
    input  wire [n-2:0] a,
    input  wire [n-2:0] b,
    input  wire [n-2:0] c,
    output wire [n-2:0] sum_out,
    output wire [n-2:0] carry_out
);

    assign sum_out = a ^ b ^ c;
    assign carry_out = (a & b) | (b & c) | (c & a);

endmodule


