module mod_mult #(
    parameter n = 5,
    parameter delta = 15,
    parameter modulus = 47
)(
    input [n-1:0] a,
    input [n-1:0] b,
    input delta_a,
    input delta_b,
    output reg [n-1:0] p,
    output reg delta_p
);


    wire [2:0] AH = a[n-1:2];
    wire [1:0] AL = a[1:0];
    wire [2:0] BH = b[n-1:2];
    wire [1:0] BL = b[1:0];

    wire [n:0] pp_ll;
    wire [n:0] pp_lh;
    wire [n:0] pp_hl;
    wire [n:0] pp_hh;

    logic_mod47_plus_LL logic_ll (
        .address({AL, delta_a, BL, delta_b}),
        .data(pp_ll)
    );

    logic_mod47_plus_LH logic_lh (
        .address({AL, delta_a, BH}),
        .data(pp_lh)
    );

    logic_mod47_plus_HL logic_hl (
        .address({AH, BL, delta_b}),
        .data(pp_hl)
    );

    logic_mod47_plus_HH logic_hh (
        .address({AH, BH}),
        .data(pp_hh)
    );

    wire [n+1:0] sum1;
    wire [n+1:1] carry1;
    wire [n:0] cout_vec;

    compressor4_2 comp0 (
        .x1(pp_ll[0]),
        .x2(pp_hl[0]),
        .x3(pp_lh[0]),
        .x4(pp_hh[0]),
        .cin(1'b0),
        .sum(sum1[0]),
        .carry(carry1[1]),
        .cout(cout_vec[0])
    );

    genvar i;
    generate
        for (i = 1; i < 6; i = i + 1) begin : compressor_stage1
            compressor4_2 comp1 (
                .x1(pp_ll[i]),
                .x2(pp_hl[i]),
                .x3(pp_lh[i]),
                .x4(pp_hh[i]),
                .cin(cout_vec[i-1]),
                .sum(sum1[i]),
                .carry(carry1[i+1]),
                .cout(cout_vec[i])
            );
        end
    endgenerate

    assign sum1[n+1] = cout_vec[n];

    wire [n:0] logic_data1;

    logic_rom_mult_plus_1 logic_rom_1 (
        .address({sum1[n+1], carry1[n+1], sum1[n], carry1[n], sum1[n-1], carry1[n-1]}),
        .data(logic_data1)
    );

    wire [n-2:0] csa_sum;
    wire [n-1:1] csa_carry;

    csa #(
        .n(n)
    ) csa_0 (
        .a(logic_data1[n-2:0]),
        .b(sum1[n-2:0]),
        .c({carry1[n-2:1], 1'b0}),
        .sum_out(csa_sum),
        .carry_out(csa_carry)
    );

    wire [n+1:0] logic_data2;

    logic_rom_mult_plus_2 logic_rom_2 (
        .address({logic_data1[n], logic_data1[n-1], csa_carry[n-1], csa_sum[n-2], csa_carry[n-2]}),
        .data(logic_data2)
    );

    wire [n-3:0] csa_sum2;
    wire [n-2:1] csa_carry2;

    csa #(
        .n(n-1)
    ) csa_1 (
        .a(logic_data2[n-3:0]),
        .b(csa_sum[n-3:0]),
        .c({csa_carry[n-3:1], 1'b0}),
        .sum_out(csa_sum2),
        .carry_out(csa_carry2)
    );

    wire [n:0] y;
    wire delta_aux;
    assign y = {logic_data2[n+1], logic_data2[n-2], csa_sum2} + {logic_data2[n], csa_carry2, 1'b0};

    assign delta_aux = logic_data2[n+1] ^ y[n];

    always @(*) begin
        p = y[n-1:0];
        delta_p = delta_aux;
    end

endmodule
